import React from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { DollarSign, Package, ArrowRightLeft, BatteryCharging } from 'lucide-react';
import { db } from '@/firebase';
import { useShop } from '@/hooks/useShop';
import { useFirebaseAuth } from '@/contexts/FirebaseAuthContext';
import { collection, getDocs, query, where, doc, updateDoc, getDoc, onSnapshot } from 'firebase/firestore';
import { reportsService } from '@/utils/reportsService';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';
import { MasterPinDialog } from '@/components/MasterPinDialog';
import { userDataService } from '@/integrations/firebase/services';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { isManualFirestoreHoldEffective } from '@/utils/manualFirestoreSyncHold';
import {
  readUserDataMergedFromLocal,
  readLastReceiptMs,
  sumAccessoryFromSalesLocalExcluding,
  addMaintenanceFromHoldBuffer,
  sumMachineChargingFromTransactions,
  sumMachineChargingFromTransactionsExcludingIds,
} from '@/utils/cashSummaryHoldLocal';

interface CashSummaryDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  userId?: string | null;
  cashBalance: number;
  walletBalances: Record<string, number>;
  transactions: any[];
}

export const CashSummaryDialog: React.FC<CashSummaryDialogProps> = ({ open, onOpenChange, userId, cashBalance, walletBalances, transactions }) => {
  const [accessorySalesToday, setAccessorySalesToday] = React.useState(0);
  const [ackAccessoryToday, setAckAccessoryToday] = React.useState(0);
  const [maintenanceTotalToday, setMaintenanceTotalToday] = React.useState(0);
  const [ackMaintenanceToday, setAckMaintenanceToday] = React.useState(0);
  const [machineChargingTotalToday, setMachineChargingTotalToday] = React.useState(0);
  const [ackMachineChargingToday, setAckMachineChargingToday] = React.useState(0);
  const [localCashBalance, setLocalCashBalance] = React.useState<number>(cashBalance || 0);
  const [lastUpdate, setLastUpdate] = React.useState(0);
  const [isReceiptPinOpen, setIsReceiptPinOpen] = React.useState(false);
  const [pendingReceiptType, setPendingReceiptType] = React.useState<'accessory' | 'maintenance' | 'machineCharging' | null>(null);
  const { toast } = useToast();
  const { shopId: shopIdCtx } = useShop() || ({} as any);
  const { user, profile } = useFirebaseAuth();
  const [isDeductReasonOpen, setIsDeductReasonOpen] = React.useState(false);
  const [deductReason, setDeductReason] = React.useState('');
  const [isDeductPinOpen, setIsDeductPinOpen] = React.useState(false);
  const [isDeductAmountOpen, setIsDeductAmountOpen] = React.useState(false);
  const [deductAmount, setDeductAmount] = React.useState('');
  const [holdTick, setHoldTick] = React.useState(0);

  React.useEffect(() => {
    const bump = () => setHoldTick((t) => t + 1);
    window.addEventListener('manualFirestoreHoldChanged', bump as EventListener);
    return () => window.removeEventListener('manualFirestoreHoldChanged', bump as EventListener);
  }, []);

  const getCashBalanceKey = () => `cashBalance_${userId || 'default'}_${(shopIdCtx || (profile as any)?.shopId || 'main')}`;
  const getGenericCashKey = () => `cashBalance_${userId || 'default'}`;

  const formatCurrency = (n: number) => `${new Intl.NumberFormat('ar-EG', { maximumFractionDigits: 0 }).format(Number(n || 0))} جنيه`;

  // 1. تحميل فلوس الإكسسوار من dailySales (الرئيسية وتحت المستخدم) مع إزالة التكرار
  React.useEffect(() => {
    if (!open || !userId) {
      if (!open) {
        setAccessorySalesToday(0);
        setAckAccessoryToday(0);
      }
      return;
    }

    let cancelled = false;

    const loadAccessorySales = async () => {
      try {
        const userDocRaw = await userDataService.getUserData(userId);
        const merged = readUserDataMergedFromLocal(userId, userDocRaw);
        const lastReceiptTime = readLastReceiptMs(merged, 'accessory');
        const lastReceiptDate = new Date(lastReceiptTime || 0);
        const lastReceiptDayStr = lastReceiptDate.toISOString().slice(0, 10);
        const holdOn = isManualFirestoreHoldEffective(userId);

        const combinedDocs: { id: string; data: any }[] = [];

        try {
          const qMain = query(
            collection(db, 'dailySales'),
            where('userId', '==', userId),
            ...(shopIdCtx ? [where('shopId', '==', shopIdCtx)] : []),
            where('date', '>=', lastReceiptDayStr)
          );
          const snapMain = await getDocs(qMain);
          snapMain.forEach(d => {
            combinedDocs.push({ id: d.id, data: d.data() });
          });
        } catch (e) {
          console.warn('Failed to load top-level dailySales for accessory:', e);
        }

        try {
          const snapUser = await getDocs(collection(db, 'users', userId, 'dailySales'));
          snapUser.forEach(d => {
            const data = d.data();
            if (shopIdCtx && data.shopId && data.shopId !== shopIdCtx) return;
            combinedDocs.push({ id: d.id, data });
          });
        } catch (e) {
          console.warn('Failed to load nested dailySales for accessory:', e);
        }

        const uniqueDocs = new Map<string, any>();
        combinedDocs.forEach(item => {
          const key = String(item.data.clientId || item.id);
          if (!uniqueDocs.has(key)) {
            uniqueDocs.set(key, item.data);
          }
        });

        /** فقط العناصر التي دخلت فعلياً في مجموع Firestore — لا نستبعد من المحلي بسبب كاش قديم لا يُحسب */
        const countedAccessoryClientKeys = new Set<string>();
        let total = 0;
        uniqueDocs.forEach((d: any, mapKey: string) => {
          if (d.isDeferred) return;

          let createdAt = 0;
          if (d.createdAt?.toDate) createdAt = d.createdAt.toDate().getTime();
          else if (d.createdAt instanceof Date) createdAt = d.createdAt.getTime();
          else if (typeof d.createdAt === 'number') createdAt = d.createdAt;
          else if (typeof d.createdAt === 'string') createdAt = new Date(d.createdAt).getTime();
          else if (d.date) {
            const timeStr = d.time || '00:00';
            createdAt = new Date(`${d.date}T${timeStr}:00`).getTime();
          }

          if (!createdAt || createdAt <= lastReceiptTime) return;

          const price = Number(d.sellingPrice ?? d.price ?? 0);
          const qty = Number(d.quantity ?? d.qty ?? 0);
          if (price > 0 && qty > 0) {
            total += price * qty;
            countedAccessoryClientKeys.add(String(d?.clientId || mapKey));
          }
        });

        if (holdOn || total === 0) {
          total += sumAccessoryFromSalesLocalExcluding(userId, shopIdCtx, lastReceiptTime, countedAccessoryClientKeys);
        }

        if (!cancelled) {
          setAccessorySalesToday(total);
          setAckAccessoryToday(0);
        }
      } catch (e) {
        console.warn('Failed to load accessory sales for cash summary:', e);
        if (!cancelled && userId) {
          try {
            const merged = readUserDataMergedFromLocal(userId, {});
            const lr = readLastReceiptMs(merged, 'accessory');
            const fallback = sumAccessoryFromSalesLocalExcluding(userId, shopIdCtx, lr, new Set());
            setAccessorySalesToday(fallback);
            setAckAccessoryToday(0);
          } catch {
            setAccessorySalesToday(0);
            setAckAccessoryToday(0);
          }
        } else if (!cancelled) {
          setAccessorySalesToday(0);
          setAckAccessoryToday(0);
        }
      }
    };

    loadAccessorySales();

    return () => {
      cancelled = true;
    };
  }, [open, userId, shopIdCtx, lastUpdate, holdTick]);

  // 2. Load other data (Maintenance, Machine Charging, Receipts)
  React.useEffect(() => {
    if (!open) return;

    const loadOtherData = async () => {
      let userDocRaw: any = {};
      try {
         if (userId) userDocRaw = await userDataService.getUserData(userId) || {};
      } catch {}
      const userDoc = userId ? readUserDataMergedFromLocal(userId, userDocRaw) : {};
      const holdOn = userId ? isManualFirestoreHoldEffective(userId) : false;

      // Maintenance
      const loadMaintenanceTotal = async () => {
        try {
          if (!userId) { setMaintenanceTotalToday(0); return; }
          
          const lastReceiptTime = readLastReceiptMs(userDoc, 'maintenance');

          let snap;
          try {
            const q = query(
              collection(db, 'maintenance_items'),
              where('userId', '==', userId)
            );
            snap = await getDocs(q);
          } catch (e) {
            snap = await getDocs(query(collection(db, 'maintenance_items'), where('userId', '==', userId)));
          }

          let totalAmount = 0;
          /** فقط البنود التي دخلت في المجموع — وإلا يُحذف المخزن المؤقت خطأً بعد الريفريش مع كاش قديم */
          const maintenanceAlreadyCountedIds = new Set<string>();
          snap.forEach(docSnap => {
            const d: any = docSnap.data();
            const status = (d.status || 'in_progress') as string;

            let createdAtMs = 0;
            if (d.createdAt?.toDate) {
              createdAtMs = d.createdAt.toDate().getTime();
            } else if (typeof d.createdAt === 'string') {
              createdAtMs = new Date(d.createdAt).getTime();
            }

            let completedAtMs = 0;
            if (d.completedAt?.toDate) {
              completedAtMs = d.completedAt.toDate().getTime();
            } else if (typeof d.completedAt === 'string') {
              completedAtMs = new Date(d.completedAt).getTime();
            }

            const referenceTime = status === 'completed'
              ? (completedAtMs || createdAtMs)
              : createdAtMs;

            if (!referenceTime || referenceTime <= lastReceiptTime) return;

            let amount = 0;
            const repair = Number(d.repairPrice || 0);
            const partial = d.partialPayment !== undefined ? Number(d.partialPayment) : NaN;

            if (status === 'completed') {
              if (Number.isFinite(repair) && repair > 0) {
                amount = repair;
              }
            } else if (Number.isFinite(partial) && partial > 0) {
              amount = partial;
            }

            if (amount > 0) {
              totalAmount += amount;
              maintenanceAlreadyCountedIds.add(docSnap.id);
            }
          });

          totalAmount = addMaintenanceFromHoldBuffer(userId, maintenanceAlreadyCountedIds, lastReceiptTime, totalAmount);
          setMaintenanceTotalToday(Math.max(0, totalAmount));
          setAckMaintenanceToday(0);
        } catch (e) {
          console.warn('فشل تحميل إجمالي فلوس الصيانة لليوم:', e);
          try {
            if (userId) {
              const merged = readUserDataMergedFromLocal(userId, userDoc);
              const lr = readLastReceiptMs(merged, 'maintenance');
              const bufOnly = addMaintenanceFromHoldBuffer(userId, new Set(), lr, 0);
              setMaintenanceTotalToday(Math.max(0, bufOnly));
              setAckMaintenanceToday(0);
            }
          } catch {
            /* ignore */
          }
        }
      };

      // Machine Charging
      const calculateMachineChargingTotal = async () => {
        try {
            if (!userId) { setMachineChargingTotalToday(0); return; }
            
            const lastReceiptTime = readLastReceiptMs(userDoc, 'machineCharging');

            const q = query(
              collection(db, 'userTransactions'),
              where('userId', '==', userId)
            );
            const snap = await getDocs(q);
            
            const machineTxIdsCountedFromFs = new Set<string>();
            let total = 0;
            snap.forEach(d => {
              const t: any = d.data();
              let tTime = 0;
              if (t.createdAt?.toDate) tTime = t.createdAt.toDate().getTime();
              else if (typeof t.createdAt === 'string') tTime = new Date(t.createdAt).getTime();
              
              if (tTime <= lastReceiptTime) return;

              const desc = String(t.description || '');
              const rawTitle = String(t.title || '');
              const isMachine = 
                t.title === 'إيصال تحويل مكينه' || 
                desc.includes('تحويل مكنه') || 
                desc.includes('تحويل مكينه') || 
                rawTitle.includes('تحويل مكنه') || 
                rawTitle.includes('تحويل مكينه');
              
              const isCompleted = t.status === 'completed' || t.status === 'confirmed';
      
              if (isMachine && isCompleted) {
                total += (Number(t.amount) || 0);
                machineTxIdsCountedFromFs.add(d.id);
              }
            });
            if (holdOn || total === 0) {
              const fromUiTx = sumMachineChargingFromTransactionsExcludingIds(
                transactions,
                lastReceiptTime,
                machineTxIdsCountedFromFs
              );
              total += fromUiTx;
            }
            setMachineChargingTotalToday(total);
            setAckMachineChargingToday(0);
        } catch (e) {
          console.warn(e);
          try {
            if (userId) {
              const lr = readLastReceiptMs(userDoc, 'machineCharging');
              setMachineChargingTotalToday(sumMachineChargingFromTransactions(transactions, lr));
            }
          } catch { /* ignore */ }
        }
      };

      // Daily Receipts & Cash Balance
      const loadDailyReceipts = async () => {
        try {
          if (!userId) { setAckAccessoryToday(0); return; }
          
          try {
            const sid = (shopIdCtx || (profile as any)?.shopId || 'main');
            const snap = await getDoc(doc(db, 'dashboardData', sid));
            if (snap.exists()) {
              const v = Number((snap.data() as any)?.cashBalance || 0);
              setLocalCashBalance(v);
              try { localStorage.setItem(`cashBalance_${userId}`, String(v)); localStorage.setItem(getCashBalanceKey(), String(v)); } catch {}
            } else {
              setLocalCashBalance(Number(userDoc?.cashBalance || cashBalance || 0));
            }
          } catch {
            setLocalCashBalance(Number(userDoc?.cashBalance || cashBalance || 0));
          }
        } catch (e) {
          setAckAccessoryToday(0);
          setAckMaintenanceToday(0);
          setAckMachineChargingToday(0);
        }
      };

      await loadMaintenanceTotal();
      await calculateMachineChargingTotal();
      await loadDailyReceipts();
    };

    loadOtherData();
  }, [open, userId, transactions, cashBalance, shopIdCtx, lastUpdate, holdTick]);

  React.useEffect(() => {
    const handler = (e: any) => {
      try {
        const v = Number(e?.detail?.value);
        if (Number.isFinite(v)) {
          setLocalCashBalance(v);
        }
      } catch {}
    };
    window.addEventListener('cashBalanceChanged', handler as EventListener);
    return () => window.removeEventListener('cashBalanceChanged', handler as EventListener);
  }, [open]);

  React.useEffect(() => {
    if (!open || !userId) return;
    const sid = (shopIdCtx || (profile as any)?.shopId || 'main');
    // استبدال onSnapshot بـ getDoc لتقليل القراءات
    const fetchDashboardData = async () => {
      try {
        const snap = await getDoc(doc(db, 'dashboardData', sid));
        if (snap.exists()) {
          const v = Number((snap.data() as any)?.cashBalance || 0);
          setLocalCashBalance(v);
          try { 
            localStorage.setItem(`cashBalance_${userId}`, String(v)); 
            localStorage.setItem(getCashBalanceKey(), String(v)); 
          } catch {}
        }
      } catch (e) {
        console.warn('Error fetching dashboard data:', e);
      }
    };
    
    fetchDashboardData();
    
    return () => { };
  }, [open, userId, shopIdCtx]);

  const effectiveAccessoryToday = Math.max(0, Number(accessorySalesToday) - Number(ackAccessoryToday));
  const effectiveMaintenanceToday = Math.max(0, Number(maintenanceTotalToday) - Number(ackMaintenanceToday));
  const effectiveMachineChargingToday = Math.max(0, Number(machineChargingTotalToday) - Number(ackMachineChargingToday));

  const handleReceipt = async (type: 'accessory' | 'maintenance' | 'machineCharging') => {
    if (!userId) return;
    const todayStr = new Date().toISOString().slice(0, 10);
    try {
      let amountToAck = 0;
      if (type === 'accessory') amountToAck = effectiveAccessoryToday;
      else if (type === 'maintenance') amountToAck = effectiveMaintenanceToday;
      else if (type === 'machineCharging') amountToAck = effectiveMachineChargingToday;

      if (amountToAck <= 0) {
        toast({ title: 'لا يوجد مبلغ لتأكيد استلامه', variant: 'default' });
        return;
      }
      const newCash = Math.max(0, Number(localCashBalance) - amountToAck);
      setLocalCashBalance(newCash);
      
      const now = new Date().toISOString();
      await userDataService.updateUserData(userId, {
        cashBalance: newCash,
        [`lastReceipt_${type}`]: now
      });

      try {
        const sid = (shopIdCtx || (profile as any)?.shopId || 'main');
        await updateDoc(doc(db, 'dashboardData', sid), { cashBalance: newCash, lastUpdated: new Date().toISOString() } as any);
      } catch { }
      try {
        localStorage.setItem(`cashBalance_${userId}`, String(newCash));
        localStorage.setItem(getCashBalanceKey(), String(newCash));
      } catch {}
      try {
        window.dispatchEvent(new CustomEvent('cashBalanceChanged', { detail: { value: newCash } }));
      } catch {}

      setLastUpdate(Date.now());
      
      let typeLabel = '';
      if (type === 'accessory') typeLabel = 'الإكسسوار';
      else if (type === 'maintenance') typeLabel = 'الصيانة';
      else typeLabel = 'مكن الشحن';

      toast({ title: 'تم الاستلام', description: `تم خصم ${amountToAck.toLocaleString('en-US', { maximumFractionDigits: 0 })} من الدرج وتصفير بند ${typeLabel}` });
    } catch (e) {
      toast({ title: 'خطأ', description: 'تعذر تنفيذ عملية تم الاستلام', variant: 'destructive' });
    }
  };

  const startDeductionFlow = () => {
    setDeductReason('');
    setDeductAmount('');
    setIsDeductReasonOpen(true);
  };

  const confirmDeductReason = () => {
    if (!deductReason.trim()) {
      toast({ title: 'سبب الخصم مطلوب', variant: 'destructive' });
      return;
    }
    setIsDeductReasonOpen(false);
    setIsDeductPinOpen(true);
  };

  const openDeductAmount = () => {
    setIsDeductPinOpen(false);
    setIsDeductAmountOpen(true);
  };

  const performDeduction = async () => {
    try {
      if (!userId) return;
      const amt = Math.max(0, Number(deductAmount || 0));
      if (!Number.isFinite(amt) || amt <= 0) {
        toast({ title: 'مبلغ غير صالح', description: 'أدخل مبلغ خصم صحيح أكبر من الصفر', variant: 'destructive' });
        return;
      }
      const newCash = Math.max(0, Number(localCashBalance) - amt);
      setLocalCashBalance(newCash);
      await userDataService.updateUserData(userId, { cashBalance: newCash });
      try {
        const sid = (shopIdCtx || (profile as any)?.shopId || 'main');
        await updateDoc(doc(db, 'dashboardData', sid), { cashBalance: newCash, lastUpdated: new Date().toISOString() } as any);
      } catch { }
      try { localStorage.setItem(`cashBalance_${userId}`, String(newCash)); } catch {}
      try {
        const timestamp = new Date().toISOString();
        localStorage.setItem(getCashBalanceKey(), String(newCash));
        localStorage.setItem(getCashBalanceKey() + '_lastUpdated', timestamp);
      } catch {}

      const tx = {
        title: 'ايصال خصم من الفلوس النقديه',
        type: 'cash_deduction',
        amount: amt,
        status: 'completed',
        createdAt: new Date(),
        note: deductReason,
        cashierName: 'الحساب الرئيسي'
      };
      try { await userDataService.saveUserTransaction(userId, tx); } catch {}

      toast({ title: 'تم الخصم', description: `تم خصم ${amt.toLocaleString('en-US', { maximumFractionDigits: 0 })} من الدرج` });
      setIsDeductAmountOpen(false);
      setDeductAmount('');
      setDeductReason('');
    } catch (e) {
      toast({ title: 'فشل الخصم', description: 'تعذر تنفيذ عملية الخصم', variant: 'destructive' });
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg animate-in fade-in-90 zoom-in-95 slide-in-from-top-4 bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800" dir="rtl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-right text-gray-900 dark:text-gray-100">
            <DollarSign className="h-5 w-5 text-emerald-600 dark:text-emerald-500" />
            تفاصيل الفلوس النقدية
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-3">
          <div className="flex items-center justify-between bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-900/50 rounded-lg p-2">
            <div className="flex items-center gap-2 text-amber-800 dark:text-amber-300 font-bold text-sm">
              <DollarSign className="h-4 w-4" />
              مجموع الفلوس النقدية (الدرج)
            </div>
            <div className="text-amber-700 dark:text-amber-400 font-extrabold text-sm">
              {formatCurrency(localCashBalance)}
            </div>
          </div>

          <div className="flex items-center justify-between bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-900/50 rounded-lg p-2">
            <div className="flex items-center gap-2 text-blue-800 dark:text-blue-300 font-bold text-sm">
              <Package className="h-4 w-4" />
              فلوس الاكسسوار
            </div>
            <div className="flex items-center gap-2">
              <div className="text-blue-700 dark:text-blue-400 font-extrabold text-sm">
                {formatCurrency(effectiveAccessoryToday)}
              </div>
              <Button
                size="sm"
                variant="ghost"
                className="h-6 px-2 rounded-lg bg-gradient-to-r from-blue-100 to-blue-200 text-blue-700 hover:from-blue-200 hover:to-blue-300 hover:text-blue-800 dark:from-blue-900/50 dark:to-blue-800/50 dark:text-blue-200 dark:hover:from-blue-800 dark:hover:to-blue-700"
                onClick={() => { setPendingReceiptType('accessory'); setIsReceiptPinOpen(true); }}
              >
                تم الاستلام
              </Button>
            </div>
          </div>

          <div className="flex items-center justify-between bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-200 dark:border-emerald-900/50 rounded-lg p-2">
            <div className="flex items-center gap-2 text-emerald-800 dark:text-emerald-300 font-bold text-sm">
              <ArrowRightLeft className="h-4 w-4" />
              فلوس الصيانة
            </div>
            <div className="flex items-center gap-2">
              <div className="text-emerald-700 dark:text-emerald-400 font-extrabold text-sm">
                {formatCurrency(effectiveMaintenanceToday)}
              </div>
              <Button
                size="sm"
                variant="ghost"
                className="h-6 px-2 rounded-lg bg-gradient-to-r from-emerald-100 to-emerald-200 text-emerald-700 hover:from-emerald-200 hover:to-emerald-300 hover:text-emerald-800 dark:from-emerald-900/50 dark:to-emerald-800/50 dark:text-emerald-200 dark:hover:from-emerald-800 dark:hover:to-emerald-700"
                onClick={() => { setPendingReceiptType('maintenance'); setIsReceiptPinOpen(true); }}
              >
                تم الاستلام
              </Button>
            </div>
          </div>

          <div className="flex items-center justify-between bg-violet-50 dark:bg-violet-950/30 border border-violet-200 dark:border-violet-900/50 rounded-lg p-2">
            <div className="flex items-center gap-2 text-violet-800 dark:text-violet-300 font-bold text-sm">
              <BatteryCharging className="h-4 w-4" />
              مكن الشحن
            </div>
            <div className="flex items-center gap-2">
              <div className="text-violet-700 dark:text-violet-400 font-extrabold text-sm">
                {formatCurrency(effectiveMachineChargingToday)}
              </div>
              <Button
                size="sm"
                variant="ghost"
                className="h-6 px-2 rounded-lg bg-gradient-to-r from-violet-100 to-violet-200 text-violet-700 hover:from-violet-200 hover:to-violet-300 hover:text-violet-800 dark:from-violet-900/50 dark:to-violet-800/50 dark:text-violet-200 dark:hover:from-violet-800 dark:hover:to-violet-700"
                onClick={() => { setPendingReceiptType('machineCharging'); setIsReceiptPinOpen(true); }}
              >
                تم الاستلام
              </Button>
            </div>
          </div>

          

          <div className="flex items-center justify-between bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-900/50 rounded-lg p-2">
            <div className="flex items-center gap-2 text-red-800 dark:text-red-300 font-bold text-sm">
              خصم فلوس من الفلوس النقديه
            </div>
            <div className="flex items-center gap-2">
              <Button
                size="sm"
                variant="ghost"
                className="h-6 px-2 rounded-lg bg-gradient-to-r from-red-100 to-red-200 text-red-700 hover:from-red-200 hover:to-red-300 hover:text-red-800 dark:from-red-900/50 dark:to-red-800/50 dark:text-red-200 dark:hover:from-red-800 dark:hover:to-red-700"
                onClick={startDeductionFlow}
              >
                خصم
              </Button>
            </div>
          </div>
        </div>

        {/* نافذة الرقم السري لعملية تم الاستلام */}
        <MasterPinDialog
          open={isReceiptPinOpen}
          onOpenChange={setIsReceiptPinOpen}
          mode="verify"
          title="تأكيد الرقم السري لعملية تم الاستلام"
          description="يرجى إدخال الرقم السري الرئيسي لتأكيد استلام المبلغ" 
          userId={userId || user?.uid}
          userRole={profile?.role}
          onSuccess={() => {
            if (pendingReceiptType) {
              handleReceipt(pendingReceiptType);
              setPendingReceiptType(null);
            }
            setIsReceiptPinOpen(false);
          }}
        />

        <Dialog open={isDeductReasonOpen} onOpenChange={setIsDeductReasonOpen}>
          <DialogContent className="sm:max-w-sm bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800">
            <DialogHeader>
              <DialogTitle className="text-gray-900 dark:text-gray-100">سبب الخصم</DialogTitle>
            </DialogHeader>
            <div className="space-y-2">
              <Label htmlFor="deduct-reason" className="text-gray-900 dark:text-gray-100">اكتب سبب الخصم</Label>
              <Input 
                id="deduct-reason" 
                value={deductReason} 
                onChange={(e) => setDeductReason(e.target.value)} 
                placeholder="سبب الخصم" 
                className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-900 dark:text-gray-100"
              />
            </div>
            <div className="flex justify-end gap-2 mt-3">
              <Button variant="outline" onClick={() => setIsDeductReasonOpen(false)} className="dark:border-gray-700 dark:text-gray-300 dark:hover:bg-gray-800">إلغاء</Button>
              <Button onClick={confirmDeductReason} className="bg-red-600 hover:bg-red-700 text-white">متابعة</Button>
            </div>
          </DialogContent>
        </Dialog>

        <MasterPinDialog
          open={isDeductPinOpen}
          onOpenChange={setIsDeductPinOpen}
          mode="verify"
          title="تأكيد الرقم السري لعملية الخصم"
          description="يرجى إدخال الرقم السري الرئيسي لمتابعة الخصم"
          userId={userId || user?.uid}
          userRole={profile?.role}
          onSuccess={openDeductAmount}
        />

        <Dialog open={isDeductAmountOpen} onOpenChange={setIsDeductAmountOpen}>
          <DialogContent className="sm:max-w-sm bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800">
            <DialogHeader>
              <DialogTitle className="text-gray-900 dark:text-gray-100">مبلغ الخصم</DialogTitle>
            </DialogHeader>
            <div className="space-y-2">
              <Label htmlFor="deduct-amount" className="text-gray-900 dark:text-gray-100">أدخل مبلغ الخصم</Label>
              <Input 
                id="deduct-amount" 
                type="number" 
                value={deductAmount} 
                onChange={(e) => setDeductAmount(e.target.value)} 
                placeholder="0.00" 
                className="bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 text-gray-900 dark:text-gray-100"
              />
            </div>
            <div className="flex justify-end gap-2 mt-3">
              <Button variant="outline" onClick={() => setIsDeductAmountOpen(false)} className="dark:border-gray-700 dark:text-gray-300 dark:hover:bg-gray-800">إلغاء</Button>
              <Button onClick={performDeduction} className="bg-red-600 hover:bg-red-700 text-white">تأكيد الخصم</Button>
            </div>
          </DialogContent>
        </Dialog>
      </DialogContent>
    </Dialog>
  );
};

export default CashSummaryDialog;
